// Generates the inline Octocode favicon constants from scripts/favicon/octocode-favicon.png.
//
//   node scripts/generate-favicon.mjs           write the generated files
//   node scripts/generate-favicon.mjs --check   fail when a generated file is stale
//
// The PNG is the octopus of octocode-mcp/assets/logo.png (512x512, no alpha) without the "octocode.ai" lettering, which is
// unreadable at favicon sizes. It was produced once with ffmpeg and is committed so this script needs no extra tool:
//
//   ffmpeg -i logo.png -vf "crop=352:352:83:40,scale=64:64:flags=lanczos,split[a][b];[a]palettegen=max_colors=32[p];[b][p]paletteuse=dither=none" octocode-favicon.png
//
// The ai and webview packages may not depend on each other or share code, so each gets its own generated copy.
import { readFile, writeFile } from "node:fs/promises";

const root = new URL("../", import.meta.url);
const png = await readFile(new URL("scripts/favicon/octocode-favicon.png", root));
const targets = ["packages/ai/src/utils/favicon.generated.ts", "packages/webview/src/favicon.generated.ts"];
const text = `// Generated by scripts/generate-favicon.mjs from scripts/favicon/octocode-favicon.png. Do not edit.
/** The Octocode octopus as a 64x64 PNG data URI, for \`<link rel="icon">\` on pages that load nothing else. */
export const OCTOCODE_FAVICON_DATA_URI = "data:image/png;base64,${png.toString("base64")}";
`;
const check = process.argv.includes("--check");
let stale = false;
for (const target of targets) {
	const url = new URL(target, root);
	if (check) {
		if ((await readFile(url, "utf8").catch(() => "")) !== text) {
			console.error(`stale: ${target}; run node scripts/generate-favicon.mjs`);
			stale = true;
		}
	} else await writeFile(url, text);
}
if (stale) process.exitCode = 1;
